using Meridian.Application.Messages;
using Meridian.Application.Outbox;
using Meridian.Application.Queue;

namespace Meridian.Web.Api;

public static class ApiEndpoints
{
    public static IEndpointRouteBuilder MapMeridianApi(this IEndpointRouteBuilder app)
    {
        var api = app.MapGroup("/api");

        api.MapPost("/messages", async (SubmitMessageRequest? request, SubmitMessage submit, CancellationToken ct) =>
        {
            var command = new SubmitMessageCommand(request?.Sender, request?.Text);
            var result = await submit.ExecuteAsync(command, ct);
            if (!result.Succeeded)
            {
                return Results.ValidationProblem(result.Errors.ToDictionary(e => e.Key, e => e.Value));
            }

            return Results.Created(
                (string?)null,
                new SubmitMessageResponse(
                    result.MessageId!.Value,
                    result.Jobs.Select(j => new SubmittedJobDto(j.JobId, j.Reference, j.IsFollowUp ? "followUp" : "created")).ToList()));
        });

        api.MapGet("/jobs", async (ListQueue listQueue, CancellationToken ct) =>
        {
            var items = await listQueue.ExecuteAsync(ct);
            return Results.Ok(items.Select(i => new JobListItemDto(
                i.Id, i.Reference, i.ReceivedAtUtc, i.Status, i.Urgency, i.Category, i.Sender, i.Preview, i.Explanation, i.SummaryEn, i.RuleIds,
                i.PropertyId, i.PropertyName, i.FollowUpCount,
                i.BuildingName, i.SuggestedContractorId, i.SuggestedContractorName, i.SuggestedContractorPhone, i.SuggestedContractorRule,
                i.EscalationState, i.EscalationAcknowledgedBy, i.EscalationAcknowledgedAtUtc)));
        });

        api.MapGet("/jobs/{id:guid}/outbound", async (Guid id, ListOutbound listOutbound, CancellationToken ct) =>
        {
            var items = await listOutbound.ExecuteAsync(id, ct);
            if (items is null)
            {
                return Results.Problem(statusCode: StatusCodes.Status404NotFound, title: "Job not found");
            }

            return Results.Ok(items.Select(o => new OutboundMessageDto(
                o.Id, o.JobId, o.Channel, o.Recipient, o.TemplateId, o.Body, o.Status, o.CreatedAtUtc)));
        });

        api.MapReviewApi();

        // Unknown API routes are 404 problem details, never the SPA page.
        api.MapFallback(() => Results.Problem(statusCode: StatusCodes.Status404NotFound, title: "Not found"));

        return app;
    }
}
using Meridian.Application.Abstractions;
using Meridian.Application.Review;
using Microsoft.AspNetCore.Mvc;

namespace Meridian.Web.Api;

/// <summary>
/// Review endpoints (R13–R15): the job detail, approve, reject and edit, plus the lists the review form needs. Every
/// action names its person in the <see cref="ActingAsHeader"/> header (no login); a missing or unknown person is 400.
/// </summary>
public static class ReviewEndpoints
{
    public const string ActingAsHeader = "X-Acting-As";

    public static RouteGroupBuilder MapReviewApi(this RouteGroupBuilder api)
    {
        api.MapGet("/staff", (StaffDirectory staff) =>
            Results.Ok(staff.All.Select(s => new StaffMemberDto(s.Id, s.Name))));

        api.MapGet("/contractors", async (IContractorRepository contractors, CancellationToken ct) =>
            Results.Ok((await contractors.ListAsync(ct))
                .OrderBy(c => c.Trade.ToString(), StringComparer.Ordinal)
                .ThenBy(c => c.Name, StringComparer.Ordinal)
                .Select(c => new ContractorDto(c.Id, c.Name, c.Trade, c.Phone))));

        api.MapGet("/properties", async (IPropertyRepository properties, CancellationToken ct) =>
            Results.Ok((await properties.ListAsync(ct))
                .OrderBy(p => p.Building?.Name, StringComparer.Ordinal)
                .ThenBy(p => p.Name, StringComparer.Ordinal)
                .Select(p => new PropertyDto(p.Id, p.Name, p.BuildingId, p.Building?.Name))));

        api.MapGet("/jobs/{id:guid}", async (Guid id, GetJob getJob, CancellationToken ct) =>
            await DetailAsync(id, getJob, ct));

        api.MapPost("/jobs/{id:guid}/approve", async (
            Guid id,
            [FromHeader(Name = ActingAsHeader)] string? actingAs,
            ReviewJob review,
            GetJob getJob,
            CancellationToken ct) =>
            await ToResultAsync(await review.ApproveAsync(id, actingAs, ct), id, getJob, ct));

        api.MapPost("/jobs/{id:guid}/reject", async (
            Guid id,
            [FromHeader(Name = ActingAsHeader)] string? actingAs,
            RejectJobRequest? request,
            ReviewJob review,
            GetJob getJob,
            CancellationToken ct) =>
            await ToResultAsync(await review.RejectAsync(id, actingAs, request?.Reason, ct), id, getJob, ct));

        api.MapPatch("/jobs/{id:guid}", async (
            Guid id,
            [FromHeader(Name = ActingAsHeader)] string? actingAs,
            EditJobRequest? request,
            ReviewJob review,
            GetJob getJob,
            CancellationToken ct) =>
        {
            var edit = new JobEdit(request?.Category, request?.Urgency, request?.UrgencyReason, request?.ContractorId, request?.PropertyId);
            return await ToResultAsync(await review.EditAsync(id, actingAs, edit, ct), id, getJob, ct);
        });

        return api;
    }

    private static async Task<IResult> ToResultAsync(ReviewResult result, Guid id, GetJob getJob, CancellationToken ct) =>
        result.Outcome switch
        {
            ReviewOutcome.Done => await DetailAsync(id, getJob, ct),
            ReviewOutcome.NotFound => JobNotFound(),
            ReviewOutcome.Invalid => Results.ValidationProblem(result.Errors.ToDictionary(e => e.Key, e => e.Value)),
            ReviewOutcome.Conflict => Results.Problem(
                statusCode: StatusCodes.Status409Conflict,
                title: "The job cannot be changed this way",
                detail: result.Detail,
                extensions: new Dictionary<string, object?> { ["missing"] = result.Missing }),
            _ => throw new InvalidOperationException($"Unknown review outcome {result.Outcome}."),
        };

    private static async Task<IResult> DetailAsync(Guid id, GetJob getJob, CancellationToken ct)
    {
        var detail = await getJob.ExecuteAsync(id, ct);
        return detail is null ? JobNotFound() : Results.Ok(ToDto(detail));
    }

    private static IResult JobNotFound() =>
        Results.Problem(statusCode: StatusCodes.Status404NotFound, title: "Job not found");

    private static JobDetailDto ToDto(JobDetail d) => new(
        d.Id,
        d.Reference,
        d.Status,
        d.Urgency,
        d.Category,
        d.ReceivedAtUtc,
        d.Explanation,
        d.SummaryEn,
        d.Language,
        d.PropertyId,
        d.PropertyName,
        d.BuildingName,
        d.Contractor is { } c ? new JobDetailContractorDto(c.Id, c.Name, c.Phone, c.Trade, c.Rule) : null,
        d.Rules.Select(r => new JobDetailRuleDto(r.Id, r.MatchedPhrase)).ToList(),
        d.Messages.Select(m => new JobDetailMessageDto(m.Id, m.Sender, m.Text, m.ReceivedAtUtc)).ToList(),
        d.Events.Select(e => new JobDetailEventDto(
            e.Type,
            e.OccurredAtUtc,
            e.Actor,
            e.Summary,
            e.Sequence,
            e.PayloadJson,
            e.Model is { } m
                ? new JobDetailModelRunDto(m.ModelId, m.PromptVersion, m.LatencyMs, m.InputTokens, m.OutputTokens, m.RawOutput, m.Reason, m.Attempts)
                : null)).ToList(),
        d.CanReview,
        d.MissingForApproval);
}
using Meridian.Application.Abstractions;
using Meridian.Domain.Jobs;
using Meridian.Domain.Messages;
using Microsoft.EntityFrameworkCore;

namespace Meridian.Infrastructure.Persistence;

internal sealed class JobRepository : IJobRepository
{
    private readonly MeridianDbContext _db;

    public JobRepository(MeridianDbContext db)
    {
        _db = db;
    }

    public async Task<long> NextJobNumberAsync(CancellationToken cancellationToken)
    {
        // One atomic statement: the UPDATE takes SQLite's write lock, so two writers never get the same number.
        var values = await _db.Database
            .SqlQueryRaw<long>(
                "UPDATE \"JobNumberSequence\" SET \"LastValue\" = \"LastValue\" + 1 WHERE \"Id\" = {0} RETURNING \"LastValue\" AS \"Value\"",
                JobNumberSequence.SingletonId)
            .ToListAsync(cancellationToken);

        return values.Count == 1
            ? values[0]
            : throw new InvalidOperationException("Job number sequence row is missing.");
    }

    public void AddMessage(Message message) => _db.Messages.Add(message);

    public void Add(Job job) => _db.Jobs.Add(job);

    public Task<Job?> GetAsync(Guid id, CancellationToken cancellationToken) =>
        _db.Jobs
            .Include(j => j.Messages)
            .Include(j => j.Events)
            .AsSplitQuery()
            .SingleOrDefaultAsync(j => j.Id == id, cancellationToken);

    public async Task<IReadOnlyList<Job>> ListOpenAtPropertiesAsync(
        IReadOnlyCollection<Guid> propertyIds,
        DateTime openedSinceUtc,
        CancellationToken cancellationToken)
    {
        if (propertyIds.Count == 0)
        {
            return Array.Empty<Job>();
        }

        var ids = propertyIds.Cast<Guid?>().ToList();
        // Times are compared in memory: the UTC converter stores ISO text, so a SQL comparison would be on strings.
        var jobs = await _db.Jobs
            .Include(j => j.Messages)
            .Include(j => j.Events)
            .AsSplitQuery()
            .Where(j => ids.Contains(j.PropertyId))
            .Where(j => j.Status != JobStatus.Attended && j.Status != JobStatus.Rejected)
            .ToListAsync(cancellationToken);
        return jobs.Where(j => j.CreatedAtUtc >= openedSinceUtc).ToList();
    }

    public async Task<IReadOnlyList<Message>> ListMessagesWithoutJobsAsync(
        DateTime receivedBeforeUtc,
        CancellationToken cancellationToken)
    {
        var messages = await _db.Messages
            .Where(m => !_db.Jobs.Any(j => j.Messages.Any(x => x.Id == m.Id)))
            .ToListAsync(cancellationToken);

        // Times are compared in memory, as above.
        return messages
            .Where(m => m.ReceivedAtUtc < receivedBeforeUtc)
            .OrderBy(m => m.ReceivedAtUtc)
            .ThenBy(m => m.Id)
            .ToList();
    }

    public Task<bool> MessageHasJobsAsync(Guid messageId, CancellationToken cancellationToken) =>
        _db.Jobs.AnyAsync(j => j.Messages.Any(m => m.Id == messageId), cancellationToken);

    public async Task<IReadOnlyList<Job>> ListEscalatingAsync(CancellationToken cancellationToken)
    {
        var jobs = await _db.Jobs
            .Include(j => j.Events)
            .Where(j => j.Urgency == Urgency.Emergency)
            .Where(j => j.Status != JobStatus.Attended && j.Status != JobStatus.Rejected)
            .Where(j => j.EscalationState == EscalationState.None
                || j.EscalationState == EscalationState.NotifiedRachel
                || j.EscalationState == EscalationState.NotifiedBackup)
            .ToListAsync(cancellationToken);
        return jobs.Where(j => j.IsEscalating).ToList();
    }

    public async Task<IReadOnlyList<Job>> ListAsync(CancellationToken cancellationToken) =>
        await _db.Jobs
            .AsNoTracking()
            .Include(j => j.Messages)
            .ToListAsync(cancellationToken);
}
using Meridian.Domain.Jobs;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;

namespace Meridian.Infrastructure.Persistence.Configurations;

internal sealed class JobEventConfiguration : IEntityTypeConfiguration<JobEvent>
{
    public void Configure(EntityTypeBuilder<JobEvent> builder)
    {
        builder.ToTable("JobEvents");
        builder.HasKey(e => e.Id);
        builder.Property(e => e.Id).ValueGeneratedNever();
        builder.Property(e => e.Type).IsRequired().HasMaxLength(64);
        builder.Property(e => e.OccurredAtUtc).IsRequired();
        builder.Property(e => e.Actor).IsRequired().HasMaxLength(JobEvent.MaxActorLength);
        builder.Property(e => e.PayloadJson).IsRequired();
        builder.Property(e => e.Sequence).IsRequired();
        builder.HasIndex(e => new { e.JobId, e.OccurredAtUtc });
        builder.HasIndex(e => new { e.JobId, e.Sequence }).IsUnique();
    }
}
using Meridian.Domain.Contractors;
using Meridian.Domain.Jobs;
using Meridian.Domain.Messages;
using Meridian.Domain.Properties;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;

namespace Meridian.Infrastructure.Persistence.Configurations;

internal sealed class JobConfiguration : IEntityTypeConfiguration<Job>
{
    public void Configure(EntityTypeBuilder<Job> builder)
    {
        builder.ToTable("Jobs");
        builder.HasKey(j => j.Id);
        builder.Property(j => j.Id).ValueGeneratedNever();
        builder.Property(j => j.Reference).IsRequired().HasMaxLength(16);
        builder.HasIndex(j => j.Reference).IsUnique();
        builder.Property(j => j.Status).IsRequired().HasMaxLength(32);
        builder.Property(j => j.Urgency).IsRequired().HasMaxLength(32);
        builder.Property(j => j.Category).IsRequired().HasMaxLength(32);
        builder.Property(j => j.ReceivedAtUtc).IsRequired();
        builder.Property(j => j.CreatedAtUtc).IsRequired();
        builder.Property(j => j.Explanation);
        builder.Property(j => j.SummaryEn);
        builder.Property(j => j.Language).HasMaxLength(16);
        builder.Ignore(j => j.HasModelOutcome);

        // Fired emergency rule ids, comma-separated (e.g. "gas,carbon-monoxide"); empty when none fired.
        builder.Ignore(j => j.RuleIds);
        builder.Property<string>("_ruleIds")
            .HasField("_ruleIds")
            .UsePropertyAccessMode(PropertyAccessMode.Field)
            .HasColumnName("RuleIds")
            .IsRequired()
            .HasMaxLength(256)
            .HasDefaultValue(string.Empty);

        builder.Ignore(j => j.FollowUpCount);
        builder.Ignore(j => j.IsOpen);

        // Escalation (AD-6): a separate field from the lifecycle status, with a time for each step.
        builder.Property(j => j.EscalationState).IsRequired().HasMaxLength(32);
        builder.Property(j => j.EscalationPrimaryNotifiedAtUtc);
        builder.Property(j => j.EscalationBackupNotifiedAtUtc);
        builder.Property(j => j.EscalationAcknowledgedAtUtc);
        builder.Property(j => j.EscalationAcknowledgedBy).HasMaxLength(JobEvent.MaxActorLength);
        builder.Property(j => j.EscalationFailedAtUtc);
        builder.HasIndex(j => j.EscalationState);
        builder.Ignore(j => j.IsEscalating);
        builder.Ignore(j => j.CanAcknowledgeEscalation);

        // Unresolved properties stay null (AD-13).
        builder.HasOne<Property>()
            .WithMany()
            .HasForeignKey(j => j.PropertyId)
            .IsRequired(false)
            .OnDelete(DeleteBehavior.Restrict);
        builder.HasIndex(j => j.PropertyId);

        // The contractor ContractorLookup suggested (R12); null means a person must choose.
        builder.HasOne<Contractor>()
            .WithMany()
            .HasForeignKey(j => j.SuggestedContractorId)
            .IsRequired(false)
            .OnDelete(DeleteBehavior.Restrict);
        builder.HasIndex(j => j.SuggestedContractorId);
        builder.Property(j => j.SuggestedContractorRule).HasMaxLength(16);

        // Many jobs per message (one per issue) and many messages per job (the first plus follow-ups).
        builder.HasMany(j => j.Messages)
            .WithMany()
            .UsingEntity<Dictionary<string, object>>(
                "JobMessages",
                right => right.HasOne<Message>().WithMany().HasForeignKey("MessageId").OnDelete(DeleteBehavior.Restrict),
                left => left.HasOne<Job>().WithMany().HasForeignKey("JobId").OnDelete(DeleteBehavior.Restrict),
                join =>
                {
                    join.ToTable("JobMessages");
                    join.HasKey("JobId", "MessageId");
                    join.HasIndex("MessageId");
                });
        builder.Navigation(j => j.Messages).UsePropertyAccessMode(PropertyAccessMode.Field);

        builder.HasMany(j => j.Events)
            .WithOne()
            .HasForeignKey(e => e.JobId)
            .OnDelete(DeleteBehavior.Restrict);
        builder.Navigation(j => j.Events).UsePropertyAccessMode(PropertyAccessMode.Field);
    }
}

